import { Mesh, Group, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, mul, add, sub, uv, sin, fract, vec3 } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new Group();

  // Load the decorative orb texture
  const tex = ctx.textureLoader.load(config.assets.imageUrl);

  // Create plane geometry (1.6:1 aspect from 512x320 atlas region)
  const geometry = new PlaneGeometry(1.6, 1);

  // Compose shader effects using TSL nodes
  const uv_coord = uv();

  // Base texture color
  const base = texture(tex);

  // Engineered gradient: subtle darkening towards bottom for machined aesthetic
  const grad_mask = sub(1.0, uv_coord.y);
  const gradient = mul(vec3(0.15, 0.12, 0.10), grad_mask);

  // Subtle grain effect: pseudo-random noise pattern
  const grain_uv = mul(uv_coord, 25.0);
  const grain_val = mul(fract(sin(add(grain_uv.x, mul(grain_uv.y, 1.5)))), 0.08);
  const grain = mul(vec3(1), grain_val);

  // Combine all effects: base + gradient + grain
  const color = add(base, add(gradient, grain));

  // Create material with composed shader
  const material = new MeshBasicNodeMaterial({
    colorNode: color,
    transparent: true
  });

  // Create and position mesh
  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, -2.85, 0.2);
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  group.add(mesh);

  // Setup resource cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  // Event handlers object (empty for static element)
  group.userData.handlers = {};

  return group;
}
